select public.prepify_load_bank('Chemistry', 7, $j$[["A reaction in which oxidation and reduction occur simultaneously is called:",["Neutralization reaction","Decomposition reaction","Redox reaction","Displacement reaction"],"C",1,0,"a43268c5546c"],["The oxidation number of an element in its free state is:",["+1","–1","0","+2"],"C",1,0,"f33cd78ca9f7"],["Which of the following is oxidized in the reaction Zn + CuSO₄ → ZnSO₄ + Cu?",["Copper","Sulphate ion","Zinc","Oxygen"],"C",1,0,"c7646430203d"],["The substance that gains electrons is called:",["Oxidizing agent","Reducing agent","Catalyst","Electrolyte"],"A",1,0,"25915bf5f6be"],["The oxidation number of sodium in NaCl is:",["–1","0","+1","+2"],"C",1,0,"974fe16ae4b7"],["In a neutral compound, the sum of oxidation numbers is:",["+1","–1","0","+2"],"C",1,0,"953f56e89a16"],["Which process causes rusting of iron?",["Reduction","Corrosion","Neutralization","Distillation"],"B",1,0,"491e86f05e5e"],["Rust mainly consists of:",["Iron sulphide","Hydrated iron oxide","Iron chloride","Iron carbonate"],"B",1,0,"af429de15706"],["The oxidation number of oxygen is usually:",["+2","–2","+1","0"],"B",1,0,"11fdec8c938c"],["Which substance acts as a reducing agent?",["One that loses electrons","One that gains electrons","One that gains oxygen","One that loses hydrogen"],"A",1,0,"0aa72e225dfd"],["The oxidation number of hydrogen in most compounds is:",["–1","+1","0","+2"],"B",1,0,"767d0d2cb6d1"],["Which of the following is a method to prevent corrosion?",["Heating","Painting","Grinding","Washing with water"],"B",1,0,"dbef28025ab1"],["Galvanization involves coating iron with:",["Copper","Aluminium","Zinc","Silver"],"C",1,0,"7d3ff8def404"],["Which metal is commonly used for sacrificial protection of ships?",["Silver","Gold","Magnesium","Copper"],"C",1,0,"69a8f9d97f08"],["In electroplating, the object to be plated acts as:",["Cathode","Anode","Electrolyte","Salt bridge"],"A",1,0,"57ba243b126b"],["The oxidation number of chlorine in NaCl is:",